// 由 scripts/gen-migrations.mjs 在构建时生成 —— 不要手改（改了也会被下一次构建覆盖）。
/* eslint-disable */
export const MIGRATIONS: ReadonlyArray<{ name: string; sql: string }> = [
  { name: "0001_init.sql", sql: "-- ============================================================================\n-- 0001_init · 拾光工作室官网 D1 初始化\n--\n-- 应用方式：\n--   本地：npx wrangler d1 execute kingcola-db --local  --file=./migrations/0001_init.sql\n--   线上：npx wrangler d1 execute kingcola-db --remote --file=./migrations/0001_init.sql\n-- ============================================================================\n\nPRAGMA foreign_keys = ON;\n\n-- ---------------------------------------------------------------------------\n-- 内容表（由 shared/resources.ts 驱动，字段名与 column 一一对应）\n-- ---------------------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS members (\n  id          TEXT PRIMARY KEY,\n  name        TEXT    NOT NULL,\n  name_en     TEXT    NOT NULL DEFAULT '',\n  title       TEXT    NOT NULL DEFAULT '',\n  direction   TEXT    NOT NULL DEFAULT '',\n  email       TEXT    NOT NULL DEFAULT '',\n  join_year   TEXT    NOT NULL DEFAULT '',\n  status      TEXT    NOT NULL DEFAULT 'current', -- current | alumni\n  is_pi       INTEGER NOT NULL DEFAULT 0,\n  bio         TEXT    NOT NULL DEFAULT '',\n  sort_order  INTEGER NOT NULL DEFAULT 0,\n  created_at  TEXT    NOT NULL,\n  updated_at  TEXT    NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_members_order ON members (is_pi DESC, join_year DESC, sort_order, name);\n\nCREATE TABLE IF NOT EXISTS projects (\n  id          TEXT PRIMARY KEY,\n  name        TEXT    NOT NULL,\n  tagline     TEXT    NOT NULL DEFAULT '',\n  description TEXT    NOT NULL DEFAULT '',\n  tags        TEXT    NOT NULL DEFAULT '[]',  -- JSON 数组\n  status      TEXT    NOT NULL DEFAULT '进行中',\n  year        TEXT    NOT NULL DEFAULT '',\n  link        TEXT    NOT NULL DEFAULT '',\n  sort_order  INTEGER NOT NULL DEFAULT 0,\n  created_at  TEXT    NOT NULL,\n  updated_at  TEXT    NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_projects_order ON projects (sort_order, year DESC, name);\n\nCREATE TABLE IF NOT EXISTS news (\n  id          TEXT PRIMARY KEY,\n  title       TEXT    NOT NULL,\n  category    TEXT    NOT NULL DEFAULT '通知公告',\n  date        TEXT    NOT NULL DEFAULT '',\n  summary     TEXT    NOT NULL DEFAULT '',\n  content     TEXT    NOT NULL DEFAULT '',\n  pinned      INTEGER NOT NULL DEFAULT 0,\n  sort_order  INTEGER NOT NULL DEFAULT 0,\n  created_at  TEXT    NOT NULL,\n  updated_at  TEXT    NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_news_order ON news (pinned DESC, date DESC, sort_order);\n\nCREATE TABLE IF NOT EXISTS slides (\n  id          TEXT PRIMARY KEY,\n  kicker      TEXT    NOT NULL DEFAULT '',\n  title       TEXT    NOT NULL,\n  subtitle    TEXT    NOT NULL DEFAULT '',\n  cta_text    TEXT    NOT NULL DEFAULT '',\n  cta_page    TEXT    NOT NULL DEFAULT 'home',\n  sort_order  INTEGER NOT NULL DEFAULT 0,\n  created_at  TEXT    NOT NULL,\n  updated_at  TEXT    NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_slides_order ON slides (sort_order, id);\n\n-- ---------------------------------------------------------------------------\n-- 站点配置（键值，值班人员可在后台修改，无需重新部署）\n-- ---------------------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS site_config (\n  key        TEXT PRIMARY KEY,\n  value      TEXT NOT NULL,\n  updated_at TEXT NOT NULL\n);\n\n-- ---------------------------------------------------------------------------\n-- 管理员（本轮设计为单用户，但表结构支持后续扩展为多人/换届交接）\n-- 密码格式：pbkdf2$<iterations>$<saltBase64>$<hashBase64>\n-- ---------------------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS admin_users (\n  id            TEXT PRIMARY KEY,\n  username      TEXT NOT NULL UNIQUE,\n  password_hash TEXT NOT NULL,\n  display_name  TEXT NOT NULL DEFAULT '',\n  is_owner      INTEGER NOT NULL DEFAULT 0,  -- 拥有者不可自我删除，保证永远有人能登录\n  last_login_at TEXT,\n  created_at    TEXT NOT NULL,\n  updated_at    TEXT NOT NULL\n);\n\n-- ---------------------------------------------------------------------------\n-- 审计日志：所有后台写操作都落一条，换届时可回溯\n-- ---------------------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS audit_logs (\n  id         TEXT PRIMARY KEY,\n  actor      TEXT NOT NULL,\n  action     TEXT NOT NULL,           -- create | update | delete | login | logout | login_failed | bootstrap\n  resource   TEXT NOT NULL DEFAULT '',\n  target_id  TEXT NOT NULL DEFAULT '',\n  detail     TEXT NOT NULL DEFAULT '',\n  ip         TEXT NOT NULL DEFAULT '',\n  ua         TEXT NOT NULL DEFAULT '',\n  created_at TEXT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs (created_at DESC);\n" },
  { name: "0002_member_avatar.sql", sql: "-- ============================================================================\n-- 0002 · 团队成员头像\n--\n-- 头像文件存 R2（key 形如 avatars/m-1-xxxx.jpg），数据库只存相对路径\n-- `/api/files/<key>`，这样本地开发与线上同源可用，将来换 R2 自定义域名也只需改一处。\n--\n-- 应用方式：\n--   本地：npx wrangler d1 execute kingcola-db --local  --file=./migrations/0002_member_avatar.sql\n--   线上：npx wrangler d1 execute kingcola-db --remote --file=./migrations/0002_member_avatar.sql\n-- ============================================================================\n\nALTER TABLE members ADD COLUMN avatar_url TEXT NOT NULL DEFAULT '';\n" },
  { name: "0003_member_destination.sql", sql: "-- ============================================================================\n-- 0003 · 拆开「负责方向」与「毕业去向」\n--\n-- 历史上只有 direction 一个字段，靠 status 切换标签与占位符来兼任两种含义，\n-- 后台编辑时容易填错。这里新增独立的 destination 列并迁移历史数据。\n--\n-- 应用方式：\n--   本地：npm run db:migrate:local\n--   线上：npm run db:migrate:remote\n-- ============================================================================\n\nALTER TABLE members ADD COLUMN destination TEXT NOT NULL DEFAULT '';\n\n-- 已毕业成员的 direction 历史上存的是毕业去向，迁移过去并去掉遗留前缀\nUPDATE members\n   SET destination = TRIM(REPLACE(direction, '毕业去向：', '')),\n       direction   = ''\n WHERE status = 'alumni'\n   AND direction <> '';\n" },
  { name: "0004_project_rebuild.sql", sql: "-- ============================================================================\n-- 0004 · 项目表改造\n--\n--   1) 主键改为自增 INTEGER（原来的 'p-1' 文本 id 不再使用）\n--   2) 删除「状态 status」与「排序权重 sort_order」\n--   3) 新增「所获荣誉 honor」与「是否精选 featured」\n--\n-- SQLite 不能修改主键类型，只能重建表再搬数据。\n--\n-- 应用方式：\n--   本地：npm run db:migrate:local\n--   线上：npm run db:migrate:remote\n-- ============================================================================\n\nPRAGMA foreign_keys = OFF;\n\nDROP INDEX IF EXISTS idx_projects_order;\n\nCREATE TABLE projects_new (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  name        TEXT    NOT NULL,\n  tagline     TEXT    NOT NULL DEFAULT '',\n  description TEXT    NOT NULL DEFAULT '',\n  tags        TEXT    NOT NULL DEFAULT '[]',\n  year        TEXT    NOT NULL DEFAULT '',\n  link        TEXT    NOT NULL DEFAULT '',\n  honor       TEXT    NOT NULL DEFAULT '',\n  featured    INTEGER NOT NULL DEFAULT 0,\n  created_at  TEXT    NOT NULL,\n  updated_at  TEXT    NOT NULL\n);\n\n-- 按年份倒序搬入，让自增 id 的顺序与原来的展示顺序一致\nINSERT INTO projects_new (name, tagline, description, tags, year, link, honor, featured, created_at, updated_at)\nSELECT name, tagline, description, tags, year, link, '', 0, created_at, updated_at\n  FROM projects\n ORDER BY year DESC, name ASC;\n\nDROP TABLE projects;\nALTER TABLE projects_new RENAME TO projects;\n\n-- ---------------------------------------------------------------------------\n-- 以下是给演示数据补的默认值，正式内容可自行在后台修改\n-- ---------------------------------------------------------------------------\n\n-- 保持首页「精选项目」不为空：把最近年份的 3 个标为精选\nUPDATE projects\n   SET featured = 1\n WHERE id IN (SELECT id FROM projects ORDER BY year DESC, id ASC LIMIT 3);\n\n-- 顺带给两个有代表性的项目填上荣誉，方便查看新字段的展示效果\nUPDATE projects SET honor = '2026 年大学生计算机设计大赛 省级一等奖' WHERE name = '智能问答知识库';\nUPDATE projects SET honor = '校图书馆优秀合作项目' WHERE name = '图书馆座位预约系统';\n\nPRAGMA foreign_keys = ON;\n" },
  { name: "0005_slide_type.sql", sql: "-- ============================================================================\n-- 0005 · 首页轮播支持两种形态\n--\n--   1) type      'text' | 'image'，历史数据一律按文字版处理\n--   2) image_url 图片版轮播的图片地址（/api/files/slides/xxx.jpg），文字版为空\n--\n-- 文字版的字段（kicker / title / subtitle）原样保留，图片版可以只用其中的\n-- 标题与按钮作图上叠加文案，也可以全部留空、只展示图片。\n--\n-- 应用方式：\n--   本地：npm run db:migrate:local\n--   线上：npm run db:migrate:remote\n-- ============================================================================\n\nALTER TABLE slides ADD COLUMN type      TEXT NOT NULL DEFAULT 'text';\nALTER TABLE slides ADD COLUMN image_url TEXT NOT NULL DEFAULT '';\n\n-- 双保险：即使哪天用别的工具建表漏了默认值，也把空值补成文字版\nUPDATE slides SET type = 'text' WHERE type IS NULL OR type = '';\n" },
  { name: "0006_applications.sql", sql: "-- ============================================================================\n-- 0006 · 招新报名（applications）\n--\n-- 一次招新里每位同学只有一条记录（student_id 唯一），状态由状态机推进：\n--   submitted → written_* → interview_* → probation → invited → member\n--   各阶段未通过落在 *_failed / rejected / declined / withdrawn\n-- 状态的中文名与允许的流转在 shared/recruit.ts，SQL 里只存取值本身。\n--\n-- 报名表文件存 R2（key 前缀 applications/），本表只存相对地址\n-- /api/files/applications/xxx.pdf —— 该前缀在 GET /api/files/* 里被拦住，\n-- 只有 GET /api/admin/applications/:id/file 带管理员会话才下载得到。\n--\n-- 时间列统一存 ISO 字符串（与其它表一致，便于直接比较与展示）。\n-- 应用方式：\n--   本地：npm run db:migrate:local\n--   线上：npm run db:migrate:remote\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS applications (\n  id                  TEXT PRIMARY KEY,\n  -- 身份（来自教务网会话，不可由学生修改）\n  student_id          TEXT NOT NULL UNIQUE,\n  name                TEXT NOT NULL DEFAULT '',\n  -- 联系方式\n  email               TEXT NOT NULL DEFAULT '',\n  phone               TEXT NOT NULL DEFAULT '',\n  qq                  TEXT NOT NULL DEFAULT '',\n  -- 报名表（R2）\n  file_url            TEXT NOT NULL DEFAULT '',\n  file_name           TEXT NOT NULL DEFAULT '',\n  file_size           INTEGER NOT NULL DEFAULT 0,\n  -- 状态机\n  status              TEXT NOT NULL DEFAULT 'submitted',\n  -- 笔试\n  written_at          TEXT NOT NULL DEFAULT '',\n  written_score       TEXT NOT NULL DEFAULT '',\n  written_note        TEXT NOT NULL DEFAULT '',\n  -- 面试\n  interview_at        TEXT NOT NULL DEFAULT '',\n  interview_note      TEXT NOT NULL DEFAULT '',\n  -- 预备期\n  probation_note      TEXT NOT NULL DEFAULT '',\n  -- 邀请函与转正\n  invite_token        TEXT NOT NULL DEFAULT '',\n  invite_expires_at   TEXT NOT NULL DEFAULT '',\n  invited_at          TEXT NOT NULL DEFAULT '',\n  confirmed_at        TEXT NOT NULL DEFAULT '',\n  member_id           TEXT NOT NULL DEFAULT '',\n  -- 管理员备注\n  note                TEXT NOT NULL DEFAULT '',\n  created_at          TEXT NOT NULL DEFAULT '',\n  updated_at          TEXT NOT NULL DEFAULT ''\n);\n\nCREATE INDEX IF NOT EXISTS idx_applications_status  ON applications(status);\nCREATE INDEX IF NOT EXISTS idx_applications_created ON applications(created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_applications_token   ON applications(invite_token);\n" },
  { name: "0007_recruit_stages.sql", sql: "-- ============================================================================\n-- 0007 · 招新报名改用「阶段 + 结果」两列描述状态，并新增发信日志\n--\n-- 背景：原来用一列 14 态枚举（submitted / written_scheduled / …）描述报名状态，\n-- 无法表达「笔试已安排但还没参加」这类组合，也不便于按阶段做统计与批量操作。\n-- 现改为两个属性：\n--\n--   stage   当前阶段：apply | written | interview | defense | onboard\n--   result  该阶段结果：''（尚无结论）| attended | passed | failed | absent | declined | withdrawn\n--\n-- 是否「已安排笔试 / 面试」不再是个人状态，而是全局周期配置（见 shared/recruit.ts 的\n-- RecruitCycleConfig，存在 site_config['runtime'].recruit），因此旧表的个人时间列\n-- written_at / interview_at / probation_note 不再需要（内容尽量搬进对应的 note）。\n--\n-- SQLite 改不动主键与列集合，沿用 0004 的做法：建新表 → 搬数据（CASE 映射旧枚举）\n-- → 删旧表 → 改名。\n--\n-- 应用方式（**有数据的库不要整体跑 migrate**，只执行本文件）：\n--   node .\\node_modules\\wrangler\\bin\\wrangler.js d1 execute kingcola-db --local \\\n--     --file=migrations/0007_recruit_stages.sql\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS applications_new (\n  id                  TEXT PRIMARY KEY,\n  -- 身份（来自教务网会话，不可由学生修改）\n  student_id          TEXT NOT NULL UNIQUE,\n  name                TEXT NOT NULL DEFAULT '',\n  -- 联系方式\n  email               TEXT NOT NULL DEFAULT '',\n  phone               TEXT NOT NULL DEFAULT '',\n  qq                  TEXT NOT NULL DEFAULT '',\n  -- 报名表（对象存储 applications/ 前缀，私有）\n  file_url            TEXT NOT NULL DEFAULT '',\n  file_name           TEXT NOT NULL DEFAULT '',\n  file_size           INTEGER NOT NULL DEFAULT 0,\n  -- 状态：阶段 + 该阶段结果\n  stage               TEXT NOT NULL DEFAULT 'apply',\n  result              TEXT NOT NULL DEFAULT '',\n  stage_changed_at    TEXT NOT NULL DEFAULT '',\n  -- 各阶段签到（扫码签到 / 后台补勾）\n  written_checkin_at   TEXT NOT NULL DEFAULT '',\n  interview_checkin_at TEXT NOT NULL DEFAULT '',\n  defense_checkin_at   TEXT NOT NULL DEFAULT '',\n  -- 成绩与评语\n  written_score       TEXT NOT NULL DEFAULT '',\n  interview_score     TEXT NOT NULL DEFAULT '',\n  defense_score       TEXT NOT NULL DEFAULT '',\n  written_note        TEXT NOT NULL DEFAULT '',\n  interview_note      TEXT NOT NULL DEFAULT '',\n  defense_note        TEXT NOT NULL DEFAULT '',\n  -- 邀请函与转正\n  invite_token        TEXT NOT NULL DEFAULT '',\n  invite_expires_at   TEXT NOT NULL DEFAULT '',\n  invited_at          TEXT NOT NULL DEFAULT '',\n  confirmed_at        TEXT NOT NULL DEFAULT '',\n  member_id           TEXT NOT NULL DEFAULT '',\n  -- 管理员备注\n  note                TEXT NOT NULL DEFAULT '',\n  created_at          TEXT NOT NULL DEFAULT '',\n  updated_at          TEXT NOT NULL DEFAULT ''\n);\n\nINSERT INTO applications_new (\n  id, student_id, name, email, phone, qq, file_url, file_name, file_size,\n  stage, result, stage_changed_at,\n  written_score, written_note, interview_note, defense_note,\n  invite_token, invite_expires_at, invited_at, confirmed_at, member_id,\n  note, created_at, updated_at\n)\nSELECT\n  id, student_id, name, email, phone, qq, file_url, file_name, file_size,\n  CASE status\n    WHEN 'submitted'           THEN 'apply'\n    WHEN 'rejected'            THEN 'apply'\n    WHEN 'written_scheduled'   THEN 'written'\n    WHEN 'written_passed'      THEN 'written'\n    WHEN 'written_failed'      THEN 'written'\n    WHEN 'interview_scheduled' THEN 'interview'\n    WHEN 'interview_passed'    THEN 'interview'\n    WHEN 'interview_failed'    THEN 'interview'\n    WHEN 'probation'           THEN 'defense'\n    WHEN 'probation_failed'    THEN 'defense'\n    WHEN 'invited'             THEN 'onboard'\n    WHEN 'member'              THEN 'onboard'\n    WHEN 'declined'            THEN 'onboard'\n    WHEN 'withdrawn'           THEN 'apply'\n    ELSE 'apply'\n  END,\n  CASE status\n    WHEN 'rejected'          THEN 'failed'\n    WHEN 'written_passed'    THEN 'passed'\n    WHEN 'written_failed'    THEN 'failed'\n    WHEN 'interview_passed'  THEN 'passed'\n    WHEN 'interview_failed'  THEN 'failed'\n    WHEN 'probation_failed'  THEN 'failed'\n    WHEN 'member'            THEN 'passed'\n    WHEN 'declined'          THEN 'declined'\n    WHEN 'withdrawn'         THEN 'withdrawn'\n    ELSE ''\n  END,\n  COALESCE(updated_at, ''),\n  COALESCE(written_score, ''),\n  COALESCE(written_note, ''),\n  COALESCE(interview_note, ''),\n  COALESCE(probation_note, ''),\n  COALESCE(invite_token, ''),\n  COALESCE(invite_expires_at, ''),\n  COALESCE(invited_at, ''),\n  COALESCE(confirmed_at, ''),\n  COALESCE(member_id, ''),\n  COALESCE(note, ''),\n  COALESCE(created_at, ''),\n  COALESCE(updated_at, '')\nFROM applications;\n\nDROP TABLE applications;\nALTER TABLE applications_new RENAME TO applications;\n\nCREATE INDEX IF NOT EXISTS idx_applications_stage   ON applications(stage, result);\nCREATE INDEX IF NOT EXISTS idx_applications_created ON applications(created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_applications_token   ON applications(invite_token);\n\n-- ============================================================================\n-- 发信日志：每次给报名同学发通知都记一行，便于回答「他到底收到没有」\n-- 与报名数据同生命周期（关闭本届时会一并清空）\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS application_mails (\n  id             TEXT PRIMARY KEY,\n  application_id TEXT NOT NULL DEFAULT '',\n  kind           TEXT NOT NULL DEFAULT '',\n  recipient      TEXT NOT NULL DEFAULT '',\n  subject        TEXT NOT NULL DEFAULT '',\n  ok             INTEGER NOT NULL DEFAULT 0,\n  code           TEXT NOT NULL DEFAULT '',\n  message        TEXT NOT NULL DEFAULT '',\n  actor          TEXT NOT NULL DEFAULT '',\n  created_at     TEXT NOT NULL DEFAULT ''\n);\n\nCREATE INDEX IF NOT EXISTS idx_application_mails_app     ON application_mails(application_id);\nCREATE INDEX IF NOT EXISTS idx_application_mails_created ON application_mails(created_at DESC);\n" },
  { name: "0008_recruit_sessions.sql", sql: "-- ============================================================================\n-- 0008 · 考试场次 + 签到二维码凭证\n--\n-- 背景：周期配置里原来只有单个 writtenAt / interviewAt（「笔试时间」就一个），\n-- 无法表达「同一轮笔试分好几个场次，同学现场任选一场」。现在把场次拆成独立表：\n--\n--   recruit_sessions        一个阶段（笔试/面试/答辩）可以有多个场次，一场一条\n--   recruit_checkin_tokens  签到二维码的凭证：绑场次 + 带过期 + 可作废、可多发\n--\n-- 为什么场次用表而不是塞进 site_config 的 JSON：\n--   1. 签到凭证要引用场次（session_id），需要稳定的主键；\n--   2. 后台按场次统计「这场来了多少人」要能走索引；\n--   3. JSON 数组的增删改要整段覆盖，两个人同时编辑会互相冲掉。\n--\n-- 签到流程（开放参加制）：\n--   后台在「笔试/面试/答辩」阶段页生成二维码（= 一个带 token 的签到链接，含失效时间），\n--   打印张贴或投屏；同学扫码 → /checkin/<token> → 填姓名 + 学号 → 记到该 token 绑定的场次上。\n--   同一场次可以重复生成二维码，旧的作废即可（revoked_at 非空 = 已作废）。\n--\n-- applications 新增三列记录「签的是哪一场」，以及 source 区分报名来源\n-- （web = 同学自己在官网提交；manual = 未报名但现场来考，管理员手工补录）。\n--\n-- 应用方式（**有数据的库不要整体跑 migrate**，只执行本文件）：\n--   node .\\node_modules\\wrangler\\bin\\wrangler.js d1 execute kingcola-db --local \\\n--     --file=migrations/0008_recruit_sessions.sql\n-- ============================================================================\n\n-- ---------------------------------------------------------------------------\n-- 考试场次\n-- ---------------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS recruit_sessions (\n  id          TEXT PRIMARY KEY,\n  -- 属于哪个阶段：written | interview | defense（与 shared/recruit.ts 的 CheckinStage 一致）\n  stage       TEXT NOT NULL DEFAULT '',\n  -- 场次名，如「第一场」「上午场」；留空时前端按顺序显示「第 N 场」\n  name        TEXT NOT NULL DEFAULT '',\n  -- 起止时间，北京时间字符串 YYYY-MM-DDTHH:mm（与周期配置同一套约定）\n  starts_at   TEXT NOT NULL DEFAULT '',\n  ends_at     TEXT NOT NULL DEFAULT '',\n  -- 地点 / 形式\n  place       TEXT NOT NULL DEFAULT '',\n  -- 备注（写进邀请函，如「请自带电脑」）\n  note        TEXT NOT NULL DEFAULT '',\n  -- 展示与邀请函里的排序\n  sort_order  INTEGER NOT NULL DEFAULT 0,\n  created_at  TEXT NOT NULL DEFAULT '',\n  updated_at  TEXT NOT NULL DEFAULT ''\n);\n\nCREATE INDEX IF NOT EXISTS idx_recruit_sessions_stage ON recruit_sessions(stage, sort_order);\n\n-- ---------------------------------------------------------------------------\n-- 签到二维码凭证\n--\n-- token 即密权：拿到它就能给某个场次签到，所以只出现在后台生成二维码时，\n-- 不进任何公开接口的返回值（学生端只用不查）。\n-- ---------------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS recruit_checkin_tokens (\n  token       TEXT PRIMARY KEY,\n  -- 签到落在哪个场次（recruit_sessions.id）；场次删除时对应的码一并失效\n  session_id  TEXT NOT NULL DEFAULT '',\n  -- 冗余阶段，签到页不必先查场次就能渲染「笔试签到」这类文案\n  stage       TEXT NOT NULL DEFAULT '',\n  -- 失效时间（ISO，带时区）：过期的码即使被拍照流出也不能再用\n  expires_at  TEXT NOT NULL DEFAULT '',\n  -- 作废时间（ISO）；非空即表示已作废（重新生成二维码时把旧的批量作废）\n  revoked_at  TEXT NOT NULL DEFAULT '',\n  created_by  TEXT NOT NULL DEFAULT '',\n  created_at  TEXT NOT NULL DEFAULT ''\n);\n\nCREATE INDEX IF NOT EXISTS idx_checkin_tokens_session ON recruit_checkin_tokens(session_id);\nCREATE INDEX IF NOT EXISTS idx_checkin_tokens_stage   ON recruit_checkin_tokens(stage, created_at DESC);\n\n-- ---------------------------------------------------------------------------\n-- applications 增列\n-- ---------------------------------------------------------------------------\n-- 签到时记下「签的是哪一场」，便于按场次统计到场人数\nALTER TABLE applications ADD COLUMN written_session_id   TEXT NOT NULL DEFAULT '';\nALTER TABLE applications ADD COLUMN interview_session_id TEXT NOT NULL DEFAULT '';\nALTER TABLE applications ADD COLUMN defense_session_id   TEXT NOT NULL DEFAULT '';\n-- 报名来源：web = 官网提交；manual = 未报名、现场来考，管理员手工补录\nALTER TABLE applications ADD COLUMN source               TEXT NOT NULL DEFAULT 'web';\n" },
  { name: "0009_recruit_no_sessions.sql", sql: "-- 0009: 去掉「场次」，签到凭证改为只绑阶段。\n--\n-- 为什么：整届的考试安排一律通过对应的 QQ 群通知，系统里不再需要知道「哪天几点在哪考」。\n-- 于是签到二维码只需要绑阶段（笔试 / 面试 / 答辩），配合自选有效期与一键作废即可 ——\n-- 同学扫哪张码就记哪个阶段，不再需要「任选一场」与按场次统计。\n--\n-- 注意：SQLite 的 ALTER TABLE ... DROP COLUMN 需要 3.35+，D1 支持。\n-- 这里只删三列、不重建 applications —— 重建会牵动索引与既有数据映射，得不偿失。\n\nDROP TABLE IF EXISTS recruit_sessions;\n\nDROP TABLE IF EXISTS recruit_checkin_tokens;\nCREATE TABLE recruit_checkin_tokens (\n  token TEXT PRIMARY KEY,\n  -- written | interview | defense\n  stage TEXT NOT NULL,\n  -- ISO 时间；过期即失效\n  expires_at TEXT NOT NULL,\n  -- 非空 = 已被管理员作废\n  revoked_at TEXT NOT NULL DEFAULT '',\n  created_by TEXT NOT NULL DEFAULT '',\n  created_at TEXT NOT NULL\n);\n\n-- 同一阶段至多一张有效码，按阶段找当前码是最常见的查询\nCREATE INDEX idx_recruit_checkin_tokens_stage ON recruit_checkin_tokens (stage, revoked_at);\n\nALTER TABLE applications DROP COLUMN written_session_id;\nALTER TABLE applications DROP COLUMN interview_session_id;\nALTER TABLE applications DROP COLUMN defense_session_id;\n" },
  { name: "0010_recruit_material_review.sql", sql: "-- ============================================================================\n-- 0010 · 报名材料审核（报名阶段后台逐个「通过 / 驳回」）\n--\n-- 背景：报名阶段管理员要在网页上判断每一份材料是否合格 ——\n-- 合格就「通过」，不合格就「驳回」，并写清理由、**发信要求同学按理由改好再交**。\n--\n-- applications 新增三列：\n--\n--   material_status       审核状态：'' 待审核（默认）/ approved 通过 / rejected 驳回\n--   material_reason       驳回理由（写给同学看，会进邮件；通过时为空）\n--   material_reviewed_at  最后一次审核时间（ISO）\n--\n-- 两条配套规则（都在代码里，不在这条迁移里）：\n--   1. **同学重新上传材料后，审核状态重置为待审核** —— 否则「改好了却还是被驳回」，\n--      而理由指向的那一版材料早就不在了；\n--   2. **未通过审核的人不能被勾选进下一阶段**（`shared/recruit.ts` 的 `isMaterialApproved`），\n--      否则审核就成了纯装饰。\n--\n-- 应用方式（**有数据的库不要整体跑 migrate**，只执行本文件）：\n--   node .\\node_modules\\wrangler\\bin\\wrangler.js d1 execute kingcola-db --local \\\n--     --file=migrations/0010_recruit_material_review.sql\n--   node .\\node_modules\\wrangler\\bin\\wrangler.js d1 execute kingcola-db --remote \\\n--     --file=migrations/0010_recruit_material_review.sql\n-- ============================================================================\n\nALTER TABLE applications ADD COLUMN material_status TEXT NOT NULL DEFAULT '';\nALTER TABLE applications ADD COLUMN material_reason TEXT NOT NULL DEFAULT '';\nALTER TABLE applications ADD COLUMN material_reviewed_at TEXT NOT NULL DEFAULT '';\n\n-- 报名阶段最常见的查询是「按审核状态筛人」（待审核 / 已驳回）\nCREATE INDEX idx_applications_material_status ON applications (material_status);\n" },
  { name: "0011_member_homepage.sql", sql: "-- ============================================================================\n-- 0011 · 成员「个人主页」链接\n--\n-- 背景：成员卡片上除了邮箱，还想放一个个人主页（博客 / GitHub / 作品集）。\n-- 与 0002（avatar_url）、0003（destination）同一路数：直接 ADD COLUMN，\n-- NOT NULL + DEFAULT '' 保证老数据读出来是空串而不是 NULL。\n--\n-- 谁写它：① 后台「团队成员」新增 / 编辑；② 正式邀请函（/invite/<token>）里本人自己填。\n--\n-- 应用方式（**有数据的库不要整体跑 migrate**，只执行本文件）：\n--   node .\\node_modules\\wrangler\\bin\\wrangler.js d1 execute kingcola-db --local \\\n--     --file=migrations/0011_member_homepage.sql\n--   （线上把 --local 换成 --remote）\n-- ============================================================================\n\nALTER TABLE members ADD COLUMN homepage_url TEXT NOT NULL DEFAULT '';\n" },
  { name: "0012_member_destination_token.sql", sql: "-- ============================================================================\n-- 0012 · 成员「毕业去向填写」凭证\n--\n-- 背景：毕业去向改为**由本人填**（像邀请函转正那样）：批量毕业时发一封信，\n-- 里面带一条专属链接 `/graduate/<token>`，同学点开填一句话就写回 members.destination。\n--\n-- 为什么凭证放在 members 上、且**不进 shared/resources.ts 的字段表**：\n--   公开的 `/api/public/bootstrap` 是按字段表逐列回传的，token 一旦进了字段表就会下发出去。\n--   所以它只存在于 worker/lib/member-destination.ts 的裸 SQL 里\n--   —— 与 `applications.invite_token` 完全同一路数。\n--\n-- 生命周期：签发时覆盖旧值（旧链接立即失效）；提交后立刻清空（一条链接只能用一次）。\n-- 刻意**没有过期时间**：毕业去向可能过几个月才回填，到点失效只会让人填不了。\n--\n-- 应用方式（**有数据的库不要整体跑 migrate**，只执行本文件）：\n--   node .\\node_modules\\wrangler\\bin\\wrangler.js d1 execute kingcola-db --local \\\n--     --file=migrations/0012_member_destination_token.sql\n--   （线上把 --local 换成 --remote）\n-- ============================================================================\n\nALTER TABLE members ADD COLUMN destination_token TEXT NOT NULL DEFAULT '';\n\n-- 按 token 找人是最常见的查询（每次打开/提交填写页都要走一次）\nCREATE INDEX IF NOT EXISTS idx_members_destination_token ON members (destination_token);\n" },
  { name: "0013_app_secrets.sql", sql: "-- 安装时自动生成的运行期密钥（安装页写、应用读）\n--\n-- 为什么放这里：运行时无法写自己的环境变量，所以「零手工安装」只能把生成的密钥存进 D1。\n-- 读取方（会话签名 / 验签）走 worker/lib/secrets.ts 的模块级缓存：每个请求入口先 warm 一次，\n-- 取不到就回退到同名环境变量（老部署、本地开发仍然照旧）。\nCREATE TABLE IF NOT EXISTS app_secrets (\n  name TEXT PRIMARY KEY,\n  value TEXT NOT NULL,\n  created_at TEXT NOT NULL\n);\n" },
]
